// Fast drop-in for makefun-diff 1.0.0 (make.fun's own line diff).
// Written from scratch for diff-speed-01-run-20261126. Returns exactly
// makefun-diff's patch for every input { old, new }.
//
// Algorithm (identical script to the reference, by construction):
//  - lines split after every '\n' ('\r' stays part of its line); a last
//    line without '\n' is a line too. Two lines are equal iff the same
//    code units, newline-or-its-absence included.
//  - common prefix kept, then common suffix of what is left.
//  - between them, Myers's greedy search: on each diagonal the path
//    reaching furthest into the old text wins; deletion wins ties;
//    no move past either text's end; every equal run followed as far
//    as it goes; first path to reach both ends is the script.
//  - patch rendered exactly as the reference renders it (hunks,
//    context 3, runs at most 6 kept lines apart share a hunk, '%'
//    after a line with no trailing newline).
//
// Speed: the fast path runs the same algorithm in the bundled WASM core
// (src/lib.rs, compiled from Rust; base64 below), which tokenizes,
// searches and renders in native code. The pure-JS implementation
// below (runJS) is the exact fallback: it is used when WASM cannot
// load, when a call traps, and for inputs with lone surrogates (which
// TextEncoder would lossy-replace). No state is kept between run()
// calls: every call interns its own lines fresh.

// ---- WASM fast path (bundled core, compiled from wasm-src/src/lib.rs) ----
// The module is instantiated synchronously at import; any failure leaves
// `wasm` null and run() uses the pure-JS implementation instead.
const WASM_B64 = '';
let wasm = null;
// The WASM core is ~5x slower under --no-incremental-marking (V8), so
// when that flag was forced on the node command line, stay on pure JS.
// (This entry's own main.ts does not set the flag.)
const _flagForced = typeof process !== 'undefined' && Array.isArray(process.execArgv) && process.execArgv.includes('--no-incremental-marking');
if (!_flagForced) {
  try {
    const bytes = Buffer.from(WASM_B64, 'base64');
    const mod = new WebAssembly.Module(bytes);
    const inst = new WebAssembly.Instance(mod, {});
    wasm = inst.exports;
  } catch { wasm = null; }
}
const _enc = new TextEncoder();
const _dec = new TextDecoder();
const _surrogate = /[\uD800-\uDFFF]/;
function runWasm(input) {
  if (_surrogate.test(input.old) || _surrogate.test(input.new)) return null;
  const oldB = _enc.encode(input.old);
  const newB = _enc.encode(input.new);
  const mem = wasm.memory;
  const oPtr = wasm.alloc(oldB.length);
  const nPtr = wasm.alloc(newB.length);
  new Uint8Array(mem.buffer).set(oldB, oPtr);
  new Uint8Array(mem.buffer).set(newB, nPtr);
  const outPtr = wasm.solve(oPtr, oldB.length, nPtr, newB.length);
  const view = new Uint8Array(mem.buffer);
  const len = view[outPtr] | (view[outPtr + 1] << 8) | (view[outPtr + 2] << 16) | (view[outPtr + 3] << 24);
  return _dec.decode(view.subarray(outPtr + 4, outPtr + 4 + len));
}

const KEEP = 0;
const DELETE = 1;
const INSERT = 2;

/** Tokenize + intern one text into the SHARED interner (both texts must
 *  share one interner, so equal lines get equal ids across texts).
 *  Returns the token array: one token per line, id * 2 + (has '\n' ? 1 : 0).
 *  `strs` holds the distinct line bodies (without '\n'), indexed by id. */
function tokenize(text, ids, strs) {
  const parts = text.split('\n');
  const last = parts.length - 1;
  const n = last === 0 && parts[0] === '' ? 0 : last + (parts[last] === '' ? 0 : 1);
  const toks = new Int32Array(n);
  let w = 0;
  for (let i = 0; i < last; i++) {
    const p = parts[i];
    let id = ids.get(p);
    if (id === undefined) { id = strs.length; ids.set(p, id); strs.push(p); }
    toks[w++] = id * 2 + 1; // every non-last line ends with '\n'
  }
  if (parts[last] !== '') {
    const p = parts[last];
    let id = ids.get(p);
    if (id === undefined) { id = strs.length; ids.set(p, id); strs.push(p); }
    toks[w++] = id * 2; // last line, no trailing '\n'
  }
  return toks;
}

/** Myers edit ops for token arrays a[0..n), b[0..m): a Uint8Array of
 *  KEEP/DELETE/INSERT, one entry per consumed line, in forward order.
 *  Assumes the caller already trimmed the common prefix/suffix.
 *  The script is exactly the reference's: same greedy search, same
 *  deletion-wins tie-break, same no-pruning rule, so the same script. */
function myersOps(a, b, n, m) {
  // Trace of V arrays, one per d, indexed by k + d. V[d][k] stores
  // X + 1 (X = old lines consumed on diagonal k after d edits), or 0
  // when that diagonal holds no path. X fits in 16 bits while the
  // texts stay under 65,000 lines, so the trace is Uint16 then
  // (half the memory and zero-fill); larger inputs use Int32.
  const VArray = n <= 65000 && m <= 65000 ? Uint16Array : Int32Array;
  const trace = [];
  // d = 0: snake from (0, 0).
  let x = 0;
  let y = 0;
  while (x < n && y < m && a[x] === b[y]) { x++; y++; }
  const v0 = new VArray(1);
  v0[0] = x + 1;
  trace.push(v0);
  if (x === n && y === m) return new Uint8Array(0);
  const kend = n - m; // only this diagonal can reach (n, m)
  let D = -1;
  let vPrev = v0;
  for (let d = 1; ; d++) {
    const vCur = new VArray(2 * d + 1);
    let done = false;
    // vDel: the stored value on diagonal k-1, carried from the
    // previous k's insertion read (its index is this k's del index).
    let vDel = 0;
    for (let k = -d, j = 0; k <= d; k += 2, j += 2) {
      // Deletion candidate: X after deleting = vDel (stored X+1 is the
      // X after the move already: X_prev + 1 = vDel).
      let xd = -1;
      if (vDel !== 0 && vDel <= n) xd = vDel;
      // Insertion candidate: read diagonal k+1 (index j), X unchanged.
      let xi = -1;
      let vIns = 0;
      if (k < d) {
        vIns = vPrev[j];
        if (vIns !== 0 && vIns - k - 2 < m) xi = vIns - 1;
      }
      vDel = vIns;
      let nx;
      if (xd >= 0 && (xi < 0 || xd >= xi)) nx = xd;
      else if (xi >= 0) nx = xi;
      else { vCur[j] = 0; continue; }
      let ny = nx - k;
      while (nx < n && ny < m && a[nx] === b[ny]) { nx++; ny++; }
      vCur[j] = nx + 1;
      if (nx === n && k === kend) { done = true; break; }
    }
    trace.push(vCur);
    if (done) { D = d; break; }
    vPrev = vCur;
  }
  // Backtrack from (n, m) on diagonal n - m. At each d the post-edit
  // point is pinned by V[d-1] (not by line equality: the line just
  // before it may coincidentally be equal too), so the snake walked
  // back is exactly x - xPost keeps long.
  const ops = new Uint8Array(n + m);
  let w = n + m;
  x = n;
  y = m;
  let k = n - m;
  for (let d = D; d >= 1; d--) {
    const vPrevD = trace[d - 1];
    let xd = -1;
    let xi = -1;
    if (k > -d) {
      const v = vPrevD[k + d - 2];
      if (v !== 0 && v <= n) xd = v;
    }
    if (k < d) {
      const v = vPrevD[k + d];
      if (v !== 0 && v - k - 2 < m) xi = v - 1;
    }
    const byDeletion = xd >= 0 && (xi < 0 || xd >= xi);
    // Post-edit point of this step.
    const xPost = byDeletion ? xd : xi;
    while (x > xPost) { x--; y--; ops[--w] = KEEP; }
    if (byDeletion) { x--; ops[--w] = DELETE; k--; }
    else { y--; ops[--w] = INSERT; k++; }
  }
  // The d = 0 snake, back to (0, 0).
  while (x > 0) { x--; y--; ops[--w] = KEEP; }
  // Exactly n + m - (#keeps) ops were written, ending at w; return the filled tail.
  return ops.subarray(w);
}

/** makefun-diff 1.0.0's answer for one case's input. */
function runJS(input) {
  if (input === null || typeof input !== 'object' || typeof input.old !== 'string' || typeof input.new !== 'string') {
    throw new TypeError('makefun-diff: the input is { old, new }, two strings');
  }
  const ids = new Map();
  const strs = [];
  const a = tokenize(input.old, ids, strs);
  const b = tokenize(input.new, ids, strs);
  const n = a.length;
  const m = b.length;

  // Common prefix, then common suffix of what is left.
  let prefix = 0;
  while (prefix < n && prefix < m && a[prefix] === b[prefix]) prefix++;
  let suffix = 0;
  while (suffix < n - prefix && suffix < m - prefix && a[n - 1 - suffix] === b[m - 1 - suffix]) suffix++;

  const midN = n - prefix - suffix;
  const midM = m - prefix - suffix;
  const midOps = midN === 0 && midM === 0
    ? new Uint8Array(0)
    : myersOps(a.subarray(prefix, n - suffix), b.subarray(prefix, m - suffix), midN, midM);

  // Full op sequence: prefix keeps, middle ops, suffix keeps.
  const ops = new Uint8Array(n + m);
  let w = 0;
  for (let i = 0; i < prefix; i++) ops[w++] = KEEP;
  ops.set(midOps, w);
  w += midOps.length;
  for (let i = 0; i < suffix; i++) ops[w++] = KEEP;

  // Change runs: maximal stretches of deletions/insertions between keeps.
  const changes = [];
  let o = 0;
  let p = 0;
  let deleted = 0;
  let inserted = 0;
  let c = null;
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    if (op === KEEP) { o++; p++; c = null; continue; }
    if (c === null) { c = { o, p, dels: 0, ins: 0 }; changes.push(c); }
    if (op === DELETE) { c.dels++; o++; deleted++; }
    else { c.ins++; p++; inserted++; }
  }

  // Hunks: change runs at most 6 kept lines apart share one.
  const hunks = [];
  for (const ch of changes) {
    const h = hunks.length === 0 ? null : hunks[hunks.length - 1];
    const prev = h === null ? null : h[h.length - 1];
    if (prev !== undefined && prev !== null && ch.o - (prev.o + prev.dels) <= 6) h.push(ch);
    else hunks.push([ch]);
  }

  const out = [`makefun-diff/1 old=${n} new=${m} hunks=${hunks.length} deleted=${deleted} inserted=${inserted}\n`];
  const lineOf = (toks, strs, idx, op) => {
    const t = toks[idx];
    const s = strs[t >> 1];
    return (t & 1) ? `${op}${s}\n` : `${op}${s}\n%\n`;
  };
  for (const h of hunks) {
    const first = h[0];
    const last = h[h.length - 1];
    const oldStart = Math.max(0, first.o - 3);
    const newStart = first.p - (first.o - oldStart);
    const after = Math.min(3, n - (last.o + last.dels));
    const oldEnd = last.o + last.dels + after;
    const newEnd = last.p + last.ins + after;
    out.push(`@ ${oldStart + 1} ${oldEnd - oldStart} ${newStart + 1} ${newEnd - newStart}\n`);
    let at = oldStart;
    for (const ch of h) {
      for (; at < ch.o; at++) out.push(lineOf(a, strs, at, '='));
      for (let i = 0; i < ch.dels; i++) out.push(lineOf(a, strs, ch.o + i, '-'));
      for (let i = 0; i < ch.ins; i++) out.push(lineOf(b, strs, ch.p + i, '+'));
      at = ch.o + ch.dels;
    }
    for (; at < oldEnd; at++) out.push(lineOf(a, strs, at, '='));
  }
  return out.join('');
}

/** makefun-diff 1.0.0's answer for one case's input. */
export function run(input) {
  if (input === null || typeof input !== 'object' || typeof input.old !== 'string' || typeof input.new !== 'string') {
    throw new TypeError('makefun-diff: the input is { old, new }, two strings');
  }
  if (wasm !== null) {
    try {
      const out = runWasm(input);
      if (out !== null) return out;
    } catch { /* fall through to the JS implementation */ }
  }
  return runJS(input);
}
